from django import forms  # Подключаем серверные формы и проверку введённых данных | from/import подключают указанные имена.
from .models import MAJORS, University  # Получаем специальности и модель университетов | from/import подключают указанные имена.
DEFAULT_PROFILE = {"ielts": 6.5, "gpa": 4.0, "budget": 15000, "major": "cs", "country": ""}  # Задаём наглядный стартовый пример профиля.
class SearchForm(forms.Form):  # Описываем пять полей подбора и их валидацию | class объявляет класс; имя в скобках — родитель, от которого наследуются возможности.
    ielts = forms.FloatField(label="IELTS", min_value=0, max_value=9, widget=forms.NumberInput(attrs={"step": "0.5"}))  # Проверяем балл IELTS; дробные значения разрешены | FloatField — поле дробного числа; min/max или validators задают границы | NumberInput — виджет числового HTML-поля; attrs задаёт его HTML-атрибуты | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница, widget — способ вывода HTML-поля, attrs — HTML-атрибуты виджета.
    gpa = forms.FloatField(label="GPA · из 5", min_value=0, max_value=5, widget=forms.NumberInput(attrs={"step": "0.1"}))  # Проверяем средний балл по шкале 0–5 | FloatField — поле дробного числа; min/max или validators задают границы | NumberInput — виджет числового HTML-поля; attrs задаёт его HTML-атрибуты | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница, widget — способ вывода HTML-поля, attrs — HTML-атрибуты виджета.
    budget = forms.IntegerField(label="Бюджет · USD / год", min_value=0, max_value=1000000)  # Принимаем целый годовой бюджет от 0 до миллиона долларов | IntegerField — поле целого числа с серверной проверкой диапазона | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница.
    major = forms.ChoiceField(label="Специальность", choices=MAJORS)  # Проверяем, что специальность входит в разрешённый список | ChoiceField — поле формы с допустимыми вариантами choices | label — подпись поля, choices — разрешённые варианты.
    country = forms.ChoiceField(label="Страна", required=False, choices=[("", "Все страны")])  # Разрешаем подбор без ограничения страны | ChoiceField — поле формы с допустимыми вариантами choices | label — подпись поля, required — обязательность заполнения, choices — разрешённые варианты.
    def __init__(self, *args, **kwargs):  # Дополняем форму актуальными странами при её создании | def объявляет функцию/метод; self — форма, *args — позиционные, **kwargs — именованные аргументы; настраивает новый экземпляр.
        super().__init__(*args, **kwargs)  # Сначала выполняем стандартную настройку формы | __init__ — метод начальной настройки экземпляра; self — текущий объект | super — даёт доступ к реализации родительского класса.
        countries = University.objects.order_by("country").values_list("country", flat=True).distinct()  # Получаем уникальные страны из базы в алфавитном порядке | distinct — убирает повторяющиеся значения результата SQL-выборки | values_list — выбирает значения полей; flat=True убирает одноэлементные кортежи | order_by — задаёт порядок SQL-выборки по указанному полю | flat — плоский результат одного поля.
        self.fields["country"].choices = [("", "Все страны")] + [(country, country) for country in countries]  # Добавляем реальные значения к пункту «Все страны».
DEFAULT_COSTS = {"tuition": 15000, "months": 12, "housing": 500, "living": 300, "travel": 600, "scholarship": 2000, "budget": 25000}  # Задаём условный пример расходов; это не реальные цены конкретной страны.
class CostForm(forms.Form):  # Проверяем семь чисел для личного расчёта расходов | class объявляет класс; имя в скобках — родитель, от которого наследуются возможности.
    tuition = forms.IntegerField(label="Обучение за год", min_value=0, max_value=1000000)  # Принимаем годовую стоимость обучения в целых долларах | IntegerField — поле целого числа с серверной проверкой диапазона | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница.
    months = forms.IntegerField(label="Месяцев проживания", min_value=1, max_value=12)  # Разрешаем от одного до двенадцати месяцев за учебный год | IntegerField — поле целого числа с серверной проверкой диапазона | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница.
    housing = forms.IntegerField(label="Жильё в месяц", min_value=0, max_value=100000)  # Проверяем ежемесячную плату за проживание | IntegerField — поле целого числа с серверной проверкой диапазона | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница.
    living = forms.IntegerField(label="Питание и другие расходы в месяц", min_value=0, max_value=100000)  # Проверяем общий месячный бюджет на повседневные траты | IntegerField — поле целого числа с серверной проверкой диапазона | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница.
    travel = forms.IntegerField(label="Перелёты за год", min_value=0, max_value=1000000)  # Учитываем всю сумму перелётов за рассматриваемый год | IntegerField — поле целого числа с серверной проверкой диапазона | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница.
    scholarship = forms.IntegerField(label="Ожидаемая стипендия за год", min_value=0, max_value=1000000)  # Получаем предполагаемую сумму финансирования, доступного для покрытия расходов | IntegerField — поле целого числа с серверной проверкой диапазона | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница.
    budget = forms.IntegerField(label="Ваш общий бюджет на год", min_value=0, max_value=10000000)  # Общий бюджет отличается от бюджета только на обучение в форме подбора | IntegerField — поле целого числа с серверной проверкой диапазона | label — подпись поля, min_value — нижняя граница, max_value — верхняя граница.
